package main

import (
	"bufio"
	"fmt"
	"os"
)

var dx = [4]int{1, -1, 0, 0}
var dy = [4]int{0, 0, 1, -1}

const INF = 1000000000

var (
	n, m, sx, sy int
	tx, ty, tp   [10]int
	tn           int
	bx, by       [10]int
	bn           int
	f            [21][21][256][256]int32
	pr           [256]int
	ans          int
	qx, qy, qt, qb [2000010]int
	l, r         int
	a            [51][51]byte
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	fmt.Fscan(reader, &n, &m)
	for i := 1; i <= n; i++ {
		var s string
		fmt.Fscan(reader, &s)
		for j := 0; j < len(s); j++ {
			a[i][j+1] = s[j]
		}
	}
	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			if a[i][j] == 'S' {
				sx, sy = i, j
			}
			if a[i][j] >= '0' && a[i][j] <= '9' {
				tx[a[i][j]-'0'] = i
				ty[a[i][j]-'0'] = j
				tn++
			}
			if a[i][j] == 'B' {
				bn++
				bx[bn] = i
				by[bn] = j
			}
		}
	}
	for i := 1; i <= tn; i++ {
		fmt.Fscan(reader, &tp[i])
	}
	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			for k := 0; k < (1 << uint(tn)); k++ {
				for t := 0; t < (1 << uint(bn)); t++ {
					f[i][j][k][t] = INF
				}
			}
		}
	}
	l, r = 1, 1
	qx[1], qy[1], qt[1], qb[1] = sx, sy, 0, 0
	f[sx][sy][0][0] = 0
	for l <= r {
		ox, oy, ot, ob := qx[l], qy[l], qt[l], qb[l]
		l++
		for k := 0; k < 4; k++ {
			nx, ny, nt, nb := ox+dx[k], oy+dy[k], ot, ob
			if a[nx][ny] != '.' && a[nx][ny] != 'S' {
				continue
			}
			for i := 1; i <= tn; i++ {
				if ny <= ty[i] {
					continue
				}
				if nx == tx[i]-1 && ox == tx[i] {
					nt ^= 1 << uint(i-1)
				}
				if ox == tx[i]-1 && nx == tx[i] {
					nt ^= 1 << uint(i-1)
				}
			}
			for i := 1; i <= bn; i++ {
				if ny <= by[i] {
					continue
				}
				if nx == bx[i]-1 && ox == bx[i] {
					nb ^= 1 << uint(i-1)
				}
				if ox == bx[i]-1 && nx == bx[i] {
					nb ^= 1 << uint(i-1)
				}
			}
			if f[nx][ny][nt][nb] > f[ox][oy][ot][ob]+1 {
				f[nx][ny][nt][nb] = f[ox][oy][ot][ob] + 1
				r++
				qx[r], qy[r], qt[r], qb[r] = nx, ny, nt, nb
			}
		}
	}
	for i := 0; i < (1 << uint(tn)); i++ {
		for j := 1; j <= tn; j++ {
			if i&(1<<uint(j-1)) != 0 {
				pr[i] += tp[j]
			}
		}
	}
	for i := 0; i < (1 << uint(tn)); i++ {
		v := pr[i] - int(f[sx][sy][i][0])
		if v > ans {
			ans = v
		}
	}
	fmt.Fprintf(writer, "%d\n", ans)
}
